/**
 * AI summary and Ask AI for one MDL's headline figures: exactly the KPIs the command page shows (JPML pending and the
 * latest report-to-report change, numbered orders, the next docketed date, the registry's partial member count and
 * Rule 702 rulings). The registry count is labelled partial so a summary never presents it as the size of the MDL.
 * Labelled AI-generated by the kit; no model or vendor is named.
 */
import { AiSummary } from "@/components/kit/ai/AiSummary";
import { AskAiButton } from "@/components/kit/ai/AskAiButton";
import { buildSectionContext } from "@/components/kit/ai/buildSectionContext";
import { headlineFigures, type Headline } from "@/components/matters/command/commandView";
import type { MdlCommandPayload } from "@/lib/matters/types";

export function MatterAi({ cmd, h }: { cmd: MdlCommandPayload; h: Headline }) {
  const figures = headlineFigures(cmd, h);
  if (!figures.length) return null;
  const title = `MDL ${cmd.mdl}: headline figures`;
  const context = buildSectionContext({
    id: "mdl-overview",
    title,
    scope: cmd.overview?.overview.title ?? cmd.lens?.mdl?.title ?? `MDL ${cmd.mdl}`,
    source: "Judicial Panel on Multidistrict Litigation; master-docket text (CourtListener RECAP)",
    figures,
  });
  return (
    <AiSummary
      context={context}
      actions={
        <AskAiButton
          sectionId="mdl-overview"
          title={title}
          context={context}
          questions={[
            "How large is this MDL, and is it growing?",
            "Which orders shape this MDL, and what is the next date on the docket?",
            "What do these figures leave out?",
          ]}
        />
      }
    />
  );
}
